class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const mkTable = (closed = false) => ({ t: 'table', map: new Map(), closed })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

class Parser {
  constructor(s) { this.s = s; this.i = 0 }
  peek() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }

  basic() {
    // at opening quote
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') { this.i++; return out }
      if (c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        this.i += 2
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
        } else fail('invalid escape \\' + String.fromCodePoint(e.codePointAt(0) === undefined ? 32 : this.s.codePointAt(this.i - 1)))
      } else { out += c; this.i++ }
    }
  }

  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return v
  }

  name() {
    const c = this.peek()
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    if (!isBare(c)) fail('expected a name')
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else { this.i = save; return parts }
    }
  }

  value(base) {
    const c = this.peek()
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === 'true') return { t: 'boolean', v: true }
    if (tok === 'false') return { t: 'boolean', v: false }
    const I = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${I}$`).test(tok)) return { t: 'integer', v: BigInt(tok.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${I}(?:\\.${I}(?:[eE][+-]?${I})?|[eE][+-]?${I})$`).test(tok)) {
      return { t: 'float', v: Number(tok.replace(/_/g, '')) }
    }
    return fail('invalid value ' + tok)
  }

  array(base) {
    this.i++
    const items = []
    this.ws()
    if (this.peek() === ']') { this.i++; return { t: 'array', items, aot: false } }
    for (;;) {
      this.ws()
      items.push(this.value([...base, `[${items.length}]`]))
      this.ws()
      const c = this.peek()
      if (c === ',') {
        this.i++
        this.ws()
        if (this.peek() === ']') { this.i++; break }
      } else if (c === ']') { this.i++; break } else fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }

  inline(base) {
    this.i++
    const tbl = mkTable(true)
    this.ws()
    if (this.peek() === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      this.pair(tbl, base, true)
      this.ws()
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === '}') { this.i++; break } else fail('unterminated inline table')
    }
    return tbl
  }

  // parse `dotted = value` and assign into tbl (paths relative to base)
  pair(tbl, base, inl) {
    const parts = this.dotted()
    this.ws()
    if (this.peek() !== '=') fail(inl ? 'expected = in an inline table' : 'expected key = value')
    this.i++
    this.ws()
    const full = [...base, ...parts]
    const v = this.value(full)
    let cur = tbl
    for (let k = 0; k < parts.length - 1; k++) {
      let n = cur.map.get(parts[k])
      const p = [...base, ...parts.slice(0, k + 1)].join('.')
      if (n === undefined) { n = mkTable(); cur.map.set(parts[k], n) }
      if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
      else if (n.t !== 'table') fail(`${p} is not a table`)
      cur = n
    }
    const last = parts[parts.length - 1]
    if (cur.map.has(last)) fail(`key ${full.join('.')} is defined twice`)
    cur.map.set(last, v)
  }
}

function parseDoc(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = mkTable()
  let cur = root
  let curPath = []
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const p = new Parser(lines[ln])
      p.ws()
      const c = p.peek()
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        const dbl = p.s[p.i + 1] === '['
        p.i += dbl ? 2 : 1
        p.ws()
        const parts = p.dotted()
        p.ws()
        const close = dbl ? ']]' : ']'
        if (p.s.slice(p.i, p.i + close.length) !== close) fail('unterminated table header')
        p.i += close.length
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        let t = root
        for (let k = 0; k < parts.length - 1; k++) {
          let n = t.map.get(parts[k])
          const path = parts.slice(0, k + 1).join('.')
          if (n === undefined) { n = mkTable(); t.map.set(parts[k], n) }
          if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
          else if (n.t !== 'table') fail(`${path} is not a table`)
          t = n
        }
        const last = parts[parts.length - 1]
        const path = parts.join('.')
        const ex = t.map.get(last)
        if (!dbl) {
          if (ex === undefined) {
            const n = mkTable(true)
            t.map.set(last, n)
            cur = n
          } else if (ex.t !== 'table') fail(`${path} is not a table`)
          else {
            if (ex.closed) fail(`table ${path} is defined twice`)
            ex.closed = true
            cur = ex
          }
        } else {
          let arr = ex
          if (ex === undefined) { arr = { t: 'array', items: [], aot: true }; t.map.set(last, arr) }
          else if (ex.t !== 'array' || !ex.aot) fail(`${path} is not an array of tables`)
          const n = mkTable(true)
          arr.items.push(n)
          cur = n
        }
        curPath = parts
        continue
      }
      p.pair(cur, curPath, false)
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${ln + 1}: ${e.message}`)
      throw e
    }
  }
  return root
}

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  switch (n.t) {
    case 'table': {
      const ks = [...n.map.keys()].sort(cmp)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'integer': return n.v.toString()
    case 'float': return JSON.stringify(n.v)
    default: return JSON.stringify(n.v)
  }
}

function keyLines(n, path, out) {
  if (n.t === 'table') {
    for (const k of [...n.map.keys()].sort(cmp)) {
      const p = path === null ? k : `${path}.${k}`
      const c = n.map.get(k)
      out.push(`${p} ${c.t}`)
      keyLines(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${c.t}`)
      keyLines(c, p, out)
    })
  }
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
try {
  const doc = parseDoc(readFileSync(0, 'utf8'))
  if (mode === 'json') process.stdout.write(toJson(doc, 0) + '\n')
  else {
    const out = []
    keyLines(doc, null, out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
"}

