        if (this.i + 1 >= this.s.length) fail('unterminated string')
        const cp = String.fromCodePoint(this.s.codePointAt(this.i + 1))
        this.i += 1 + cp.length
        if (cp === '"') out += '"'
        else if (cp === '\\') out += '\\'
        else if (cp === 'n') out += '\n'
        else if (cp === 't') out += '\t'
        else if (cp === 'r') out += '\r'
        else if (cp === '0') out += '\0'
        else if (cp === 'u') {
